const tab=[46,47,18,2,53,8,23,32,15,50,10,31,58,3,45,35,27,43,5,49,33,9,42,19,29,28,14,39,12,38,41,13,37,48,7,16,24,55,40,61,26,17,0,1,60,51,30,4,22,25,54,21,56,59,6,63,57,62,11,36,20,34,44,52];
const cfg=$('填写 UID 和页数').first().json;
const w=$json.data?.wbi_img;
if(!w?.img_url||!w?.sub_url) throw new Error('没有拿到 WBI 钥匙，请稍后重试或切换 data_mode=demo');
const key=u=>u.split('/').pop().split('.')[0];
const raw=key(w.img_url)+key(w.sub_url);
const mixin=tab.map(i=>raw[i]||'').join('').slice(0,32);
const params={mid:cfg.uid,pn:1,ps:cfg.page_size,tid:0,keyword:'',order:'pubdate',platform:'web',web_location:1550101,wts:Math.floor(Date.now()/1000)};
const clean=v=>String(v).replace(/[!'()*]/g,'');
const query=Object.keys(params).sort().map(k=>encodeURIComponent(k)+'='+encodeURIComponent(clean(params[k]))).join('&');
return [{json:{query,sign_source:query+mixin,mixin}}];

if($json.code!==0) throw new Error('B站接口返回 '+$json.code+': '+($json.message||'未知错误')+'。请把 data_mode 改成 demo 后重跑。');
const cfg=$('填写 UID 和页数').first().json;
const nav=$('生成第一页签名原文').first().json;
const total=Number($json.data?.page?.count||0);
const actual=Math.max(1,Math.min(Number(cfg.max_pages)||1,Math.ceil(total/Number(cfg.page_size||30))||1,3));
const clean=v=>String(v).replace(/[!'()*]/g,'');
const rows=[];
for(let pn=1;pn<=actual;pn++){
 const params={mid:cfg.uid,pn,ps:cfg.page_size,tid:0,keyword:'',order:'pubdate',platform:'web',web_location:1550101,wts:Math.floor(Date.now()/1000)};
 const query=Object.keys(params).sort().map(k=>encodeURIComponent(k)+'='+encodeURIComponent(clean(params[k]))).join('&');
 rows.push({json:{page:pn,query,sign_source:query+nav.mixin}});
}
return rows;

const d=$json.data||$json;
const s=d.stat||{};
const view=Number(s.view||0);
const pct=n=>view?Math.round(Number(n||0)/view*10000)/100:0;
const pub=Number(d.pubdate||d.ctime||0);
return [{json:{
 数据模式:d.is_demo?'教学样本':'真实公开数据',
 标题:d.title||'',作者:d.owner?.name||d.author||'',
 发布时间:pub?new Date(pub*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'',
 时长秒:Number(d.duration||0),播放:Number(s.view||0),弹幕:Number(s.danmaku||0),评论:Number(s.reply||0),点赞:Number(s.like||0),投币:Number(s.coin||0),收藏:Number(s.favorite||0),分享:Number(s.share||0),
 收藏率百分比:pct(s.favorite),互动率百分比:pct(Number(s.like||0)+Number(s.coin||0)+Number(s.favorite||0)+Number(s.share||0)),
 封面:d.pic||'',视频链接:d.bvid?('https://www.bilibili.com/video/'+d.bvid):''
}}];
